package com.company.tpm.score;import java.math.*;import org.springframework.stereotype.Service;
@Service public class ScoreService{public record Result(BigDecimal percentage,boolean passed){}public Result calculate(BigDecimal score,BigDecimal maximum,BigDecimal passMark){if(score==null||maximum==null||passMark==null||maximum.signum()<=0||score.signum()<0||score.compareTo(maximum)>0)throw new IllegalArgumentException("Score must be between 0 and maximum score");var pct=score.multiply(BigDecimal.valueOf(100)).divide(maximum,2,RoundingMode.HALF_UP);return new Result(pct,pct.compareTo(passMark)>=0);}}
